import os, sys, json

def inspect():
    cwd = os.getcwd()
    parent = os.path.abspath(os.path.join(cwd, '..'))
    return {
        'cwd': cwd,
        'cwd_contents': os.listdir(cwd) if os.path.exists(cwd) else [],
        'parent_dir': parent,
        'parent_contents': os.listdir(parent) if os.path.exists(parent) else []
    }

